import storeLabelList from "@/components/storeLabelList";
export default {
  name: 'c_goods_label',
  components: {
    storeLabelList: storeLabelList
  },
  props: {
    configObj: {
      type: Object
    },
    configNme: {
      type: String
    },
    number: {
      type: null
    }
  },
  data: function data() {
    return {
      defaults: {},
      configData: {},
      timeStamp: '',
      storeLabelShow: false
    };
  },
  mounted: function mounted() {
    var _this = this;
    this.$nextTick(function () {
      _this.defaults = _this.configObj;
      _this.configData = _this.configObj[_this.configNme];
    });
  },
  watch: {
    configObj: {
      handler: function handler(nVal, oVal) {
        this.defaults = nVal;
        this.configData = nVal[this.configNme];
      },
      deep: true
    },
    number: function number(nVal) {
      this.timeStamp = nVal;
    }
  },
  methods: {
    openStoreLabel: function openStoreLabel(row) {
      this.storeLabelShow = true;
      this.$refs.storeLabel.storeLabel(JSON.parse(JSON.stringify(this.configData.list)));
    },
    closeStoreLabel: function closeStoreLabel(label) {
      var index = this.configData.list.indexOf(this.configData.list.filter(function (d) {
        return d.id == label.id;
      })[0]);
      this.configData.list.splice(index, 1);
      this.getLabelId(this.configData.list);
    },
    activeStoreData: function activeStoreData(storeDataLabel) {
      this.storeLabelShow = false;
      this.configData.list = storeDataLabel;
      this.getLabelId(storeDataLabel);
    },
    getLabelId: function getLabelId(storeDataLabel) {
      var storeActiveIds = [];
      storeDataLabel.forEach(function (item) {
        storeActiveIds.push(item.id);
      });
      this.configData.activeValue = storeActiveIds;
      this.$emit('getConfig', {
        name: 'goodsLabel'
      });
    },
    // 标签弹窗关闭
    storeLabelClose: function storeLabelClose() {
      this.storeLabelShow = false;
    }
  }
};
